import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceMaterialMainDelta {
 static final String P="local/lito381/server/",OWNER=P+"NativeLightAction",H=P+"NativeSourceMaterialMain";
 static void need(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var jar=new JarFile(a[1])){
  var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(old.entries())){names.add(e.getName());var n=jar.getJarEntry(e.getName());need(n!=null,"original entry retained");if(!Arrays.equals(old.getInputStream(e).readAllBytes(),jar.getInputStream(n).readAllBytes()))changed.add(e.getName());}need(changed.equals(Set.of(OWNER+".class")),"one original native light owner only");var added=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))added.add(e.getName());need(added.equals(Set.of(H+".class")),"one fieldless Main guard only");
  var before=FreezeAcceptedMethods.read(old,OWNER);var after=FreezeAcceptedMethods.read(jar,OWNER);need(before.fields.size()==after.fields.size()&&before.methods.size()==after.methods.size(),"no field or method replacement/addition");
  for(int i=0;i<before.fields.size();i++){var f=before.fields.get(i);var g=after.fields.get(i);need(f.name.equals(g.name)&&f.desc.equals(g.desc)&&f.access==g.access&&Objects.equals(f.signature,g.signature)&&Objects.equals(f.value,g.value),"original fields exact");}
  int methods=0,prefixes=0;for(var original:before.methods){var m=after.methods.stream().filter(x->x.name.equals(original.name)&&x.desc.equals(original.desc)).findFirst().orElseThrow();for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(H)){
   need(Set.of("ready","locked").contains(call.name),"only bounded lifetime/Main guard");boolean locked=call.name.equals("locked"),reserve=Set.of("reserve","nativeSourceMaterialPairOriginalReserve","nativeSourceMaterialPairIngress").contains(m.name);
   for(int slot:locked?new int[]{1,0}:new int[]{0}){var load=FreezeAcceptedMethods.prev(call);need(load instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==slot,"exact original first argument");m.instructions.remove(load);}var branch=FreezeSourceTargetDelta.next(call);need(branch.getOpcode()==IFNE,"one guard branch");var ret=FreezeSourceTargetDelta.next(branch);if(reserve){need(ret.getOpcode()==ACONST_NULL,"reserve rejection keeps no receipt");var next=FreezeSourceTargetDelta.next(ret);need(next.getOpcode()==ARETURN,"reserve prefix returns null");m.instructions.remove(next);}else need(ret.getOpcode()==RETURN,"void rejection prefix");for(var node:List.of(call,branch,ret))m.instructions.remove(node);prefixes++;
  }need(Arrays.equals(SourceNpcFirstViewDelta.body(before,original,original.name),SourceNpcFirstViewDelta.body(after,m,original.name)),"whole original native body inverse "+original.name);methods++;}
  need(prefixes==7,"seven and only seven Main/first-lifetime prefixes");System.out.println("PASS independent material Main inverse: "+methods+" complete original methods,7 guard prefixes,0 fields,0 original method additions; original WORLD/Ctrl/cost/RNG/reserve/fence/transfer/rollback/cleanup retained");
 }}
}
